   {"jsonrpc": "2.0", "id": "req-1", "method": "message/send", "params": {...}}

   // Response (returns Task)
   {"jsonrpc": "2.0", "id": "req-1", "result": {"task": {"id": "task-123", ...}}}

   // Response (returns Message, if streaming enabled)
   {"jsonrpc": "2.0", "id": "req-1", "result": {"message": {"role": "agent", ...}}}
